  "ancrage:b": ["tera-ancragevendredi-b"]
};

// Champs de marque fixes, injectés à chaque appel de la famille/variante correspondante — jamais
// laissés à la charge de Claude.
const STATIC_FIELDS = {
  "declic:traiteur": { tag: "LE DÉCLIC · TRAITEUR", devise: "FCFA" },
  "declic:eventplanning": { tag: "LE DÉCLIC · EVENT PLANNING" },
  "savoirfaire:generique": {},
  "savoirfaire:chiffre": { edition_label: "Le chiffre du mercredi" },
  "savoirfaire:traiteur": {},
  "ancrage:a": { tag: "L'ANCRAGE DU VENDREDI" },
  "ancrage:b": { tag: "L'ANCRAGE DU VENDREDI", cta_label: "Demander un devis →" }
};

function buildVisualRequests(d) {
  const key = `${d.famille}:${d.variante}`;
  const isChiffreDuMercredi = key === "savoirfaire:chiffre";
  const templates = TEMPLATE_MAP[key];
  if (!templates) {
    throw new Error(`Aucun gabarit défini pour famille="${d.famille}" variante="${d.variante}".`);
  }

  const slides = Array.isArray(d.slides) ? d.slides : [];
  const hashtagsText = Array.isArray(d.hashtags) ? d.hashtags.join(" ") : (d.hashtags || "");
  const caption = [d.caption, hashtagsText].filter(Boolean).join("\n\n");
  const postId = $execution.id + "-" + d.jour;
  const backgroundImages = Array.isArray(d.background_images) ? d.background_images : [];

  // La grande valeur de la slide 2 doit rester aussi courte que dans le gabarit Figma.
  // Si une phrase a �t� produite, reprendre le chiffre et l'unit� de la couverture.
  if (isChiffreDuMercredi && slides[1] && String(slides[1].statistique || "").length > 14) {
    const chiffre = String(slides[0]?.chiffre || "").trim();
    const unite = String(slides[0]?.unite || "").trim();
    slides[1] = { ...slides[1], statistique: [chiffre, unite].filter(Boolean).join(" ") };
  }

  // Les formulations interrogatives doivent toujours porter leur ponctuation, m�me si le
  // mod�le l'a omise. Cette normalisation s'applique au titre et aux trois questions de la slide 3.
  if (isChiffreDuMercredi && slides[2]) {
    const withQuestionMark = (value) => {
      const text = String(value || "").trim();
      if (!/^(pourquoi|comment|qui|que|quel|quelle|quels|quelles|quand|o�|combien)\b/i.test(text)) return text;
      return text.replace(/[.!?…]+$/u, "").trim() + " ?";
    };
    slides[2] = {
      ...slides[2],
      titre: withQuestionMark(slides[2].titre),
      conseil1_titre: withQuestionMark(slides[2].conseil1_titre),
      conseil2_titre: withQuestionMark(slides[2].conseil2_titre),
      conseil3_titre: withQuestionMark(slides[2].conseil3_titre)
    };
  }

  return templates.map((template, idx) => {
    const slideFields = slides[idx] || {};
    // L'image est choisie en amont dans la banque média, indépendamment de la rédaction Claude.
    // Une image propre à la slide est prioritaire, puis celle de la liste du carrousel, puis le
    // fond commun de la publication. Sans image fournie, le fond Figma canonique reste le fallback.
    const backgroundImage = isChiffreDuMercredi
      ? undefined
      : (slideFields.background_image || backgroundImages[idx] || d.background_image);
    const backgroundPosition = isChiffreDuMercredi
      ? undefined
      : (slideFields.background_position || d.background_position);
    return {
      json: {
        post_id: postId,
        jour: d.jour,
        famille: d.famille,
        variante: d.variante,
        template,
        slide_index: idx + 1,
        slide_count: templates.length,
        target_due_at: d.target_due_at,
        render_body: {
          ...STATIC_FIELDS[key],
          ...slideFields,
          ...(backgroundImage ? { background_image: backgroundImage } : {}),
          ...(backgroundPosition ? { background_position: backgroundPosition } : {})
        },
        caption
      }
    };
  });
}

return $input.all().flatMap(item => buildVisualRequests(item.json));

// n8n node mode: runOnceForAllItems
// Les appels externes peuvent livrer les rendus en plusieurs vagues. Ce collecteur n'émet rien
// tant que les trois jours et toutes les slides attendues ne sont pas présents.
const state = $getWorkflowStaticData("global");
if (!state.weeklyPackAccumulator) state.weeklyPackAccumulator = {};

const executionKey = String($execution.id);
const existing = Array.isArray(state.weeklyPackAccumulator[executionKey])
  ? state.weeklyPackAccumulator[executionKey]
  : [];

const incoming = $input.all().map(item => item.json);
const merged = [...existing, ...incoming];
const unique = new Map();

for (const item of merged) {
  const key = `${item.post_id || item.jour}:${item.slide_index || 1}`;
  unique.set(key, item);
}

const collected = [...unique.values()];
state.weeklyPackAccumulator[executionKey] = collected;

const requiredDays = ["Lundi", "Mercredi", "Vendredi"];
const complete = requiredDays.every(jour => {
  const slides = collected.filter(item => item.jour === jour);
  if (!slides.length) return false;
  const expected = Number(slides[0].slide_count || 1);
  return slides.length >= expected;
});

if (!complete) return [];

delete state.weeklyPackAccumulator[executionKey];
return collected.map(json => ({ json }));

// "Préparer Pack Hebdomadaire" — regroupe les publications des 3 créneaux de la semaine (lundi,
// mercredi, vendredi) et construit le formulaire de validation groupé, sur le modèle éprouvé de
// La Lignée (code_hebdo_prepare_pack.js) : un seul geste de validation le dimanche plutôt que 3
// validations séparées dans la semaine.

function escapeHtml(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;")
    .replace(/\n/g, "<br>");
}

// Les gabarits TERA n'ont pas de champ "titre" unique et commun (titre/headline/citation/chiffre
// selon la famille) — on prend le premier qui existe pour l'aperçu du pack.
function titleFor(renderBody) {
  return renderBody.titre || renderBody.headline || renderBody.citation || renderBody.chiffre || "";
}

const items = $input.all();
const byJour = {};
items.forEach(it => {
  const j = it.json.jour;
  if (!byJour[j]) byJour[j] = [];
  byJour[j].push(it.json);
});

const jourOrder = ["Lundi", "Mercredi", "Vendredi"];

const slots = jourOrder
  .filter(j => byJour[j])
  .map(jour => {
    const group = byJour[jour].sort((a, b) => (a.slide_index || 1) - (b.slide_index || 1));
    const hero = group.find(g => g.slide_index === 1) || group[0];
    const caption = group[0].caption;
    const rawTitle = titleFor(hero.render_body || {});
    // Une génération dont la réponse Claude n'a pas pu être parsée dégrade gracieusement en amont
    // plutôt que de planter, mais laisse ce créneau sans titre ni légende — à signaler clairement
    // ici plutôt que d'afficher un aperçu vide sans explication.
    const looksFailed = !caption && !rawTitle;
    const titleText = rawTitle || `${jour} — ${group[0].famille}/${group[0].variante}`;
    return {
      jour,
      famille: group[0].famille,
      variante: group[0].variante,
      heroImageUrl: hero.url,
      titleText,
      caption,
      looksFailed,
      renderItems: group
    };
  });

const fields = [];
slots.forEach(s => {
  const warningBanner = s.looksFailed
    ? `<p style="color:#b00; font-weight:bold;">⚠️ La génération a échoué pour cette publication (réponse non exploitable). Choisissez "Modifier" pour la régénérer automatiquement, un commentaire n'est pas nécessaire.</p>`
    : "";
  fields.push({
    fieldLabel: " ",
    fieldType: "html",
    html: `<h3>${escapeHtml(s.jour)} — ${escapeHtml(s.famille)} / ${escapeHtml(s.variante)}</h3>${warningBanner}<img src="${s.heroImageUrl}" style="max-width:320px;border-radius:8px" /><p><b>${escapeHtml(s.titleText)}</b></p><p>${escapeHtml(s.caption)}</p>`
  });
  fields.push({
    fieldLabel: `${s.jour} — décision`,
    fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Valider" }, { option: "Modifier" }, { option: "Refuser" }] },
    requiredField: true
  });
  fields.push({
    fieldLabel: `${s.jour} — Commentaire (si Modifier)`,
    fieldType: "textarea",
    requiredField: false
  });
});

return [{
  json: {
    slots,
    formFieldsJson: JSON.stringify(fields, null, 2)
  }
}];

// "Traiter la Validation Hebdomadaire" — répartit les décisions du formulaire de validation
// (une ligne Valider/Modifier/Refuser + commentaire par créneau) vers les branches de routage.

const formData = $("Envoyer Pack de Validation").item.json.data;
const slots = $("Préparer Pack Hebdomadaire").item.json.slots;
const pilierConfig = $("Préparer les 3 publications").all().map(i => i.json);

const results = [];
slots.forEach(s => {
  const decision = formData[`${s.jour} — décision`];
  const commentaire = formData[`${s.jour} — Commentaire (si Modifier)`] || "";
  const config = pilierConfig.find(c => c.jour === s.jour) || {};
  results.push({
    json: {
      jour: s.jour,
      famille: s.famille,
      variante: s.variante,
      attempt: config.attempt || 1,
      target_due_at: config.target_due_at,
      decision,
      commentaire,
      renderItems: s.renderItems
    }
  });
});

return results;

// "Préparer Buffer" — transforme une publication validée en requête de programmation.
// Les identifiants de canaux sont lus depuis l'environnement n8n, jamais écrits dans le code.

const CHANNELS = {
  facebook: $env.BUFFER_CHANNEL_FACEBOOK,
  instagram: $env.BUFFER_CHANNEL_INSTAGRAM,
  linkedin: $env.BUFFER_CHANNEL_LINKEDIN
};

const missing = Object.entries(CHANNELS)
  .filter(([, value]) => !value)
  .map(([name]) => name);

if (missing.length) {
  throw new Error(`Canaux Buffer manquants : ${missing.join(", ")}. Renseigne les variables BUFFER_CHANNEL_* dans l'environnement n8n.`);
}

const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess { post { id text dueAt } }
    ... on MutationError { message }
  }
}`;

function buildBufferRequests(d) {
  if (d.decision !== "Valider") return [];

  const renderItems = Array.isArray(d.renderItems) ? d.renderItems : [];
  const media = [...renderItems]
    .sort((a, b) => (a.slide_index || 1) - (b.slide_index || 1))
    .map(item => item.url)
    .filter(Boolean);

  if (!media.length) throw new Error(`Aucun visuel rendu pour la publication du ${d.jour}.`);

  const caption = renderItems[0]?.caption || d.caption || "";
  if (!caption) throw new Error(`Aucune légende disponible pour la publication du ${d.jour}.`);

  return Object.entries(CHANNELS).map(([network, channelId]) => ({
    json: {
      post_id: renderItems[0]?.post_id,
      jour: d.jour,
      network,
      channel_id: channelId,
      due_at: d.target_due_at,
      text: caption,
      media,
      status: "pending_buffer",
      graphql_body: {
        query: mutation,
        variables: {
          input: {
            text: caption,
            channelId,
            assets: media.map(url => ({ image: { url } })),
            schedulingType: "automatic",
            mode: "customScheduled",
            dueAt: d.target_due_at,
            ...(network === "facebook" ? { metadata: { facebook: { type: "post" } } } : {}),
            ...(network === "instagram" ? { metadata: { instagram: { type: "post", shouldShareToFeed: true } } } : {})
          }
        }
      }
    }
  }));
}

return $input.all().flatMap(item => buildBufferRequests(item.json));

// n8n node mode: runOnceForEachItem
// Buffer peut renvoyer une erreur métier dans une réponse HTTP 200. Sans ce contrôle, n8n
// considère à tort la programmation comme réussie.
const response = $json;
const result = response?.data?.createPost;

if (!result) {
  throw new Error("Buffer n'a renvoyé aucun résultat createPost.");
}

if (result.message) {
  throw new Error(`Buffer a refusé la programmation : ${result.message}`);
}

if (!result.post?.id) {
  throw new Error("Buffer n'a créé aucune publication et n'a fourni aucun identifiant.");
}

return {
  json: {
    buffer_post_id: result.post.id,
    due_at: result.post.dueAt,
    status: "scheduled"
  }
};

// "Préparer Régénération" — renvoie les publications à modifier vers la préparation du prompt.
// Le commentaire humain est prioritaire ; en cas d'échec technique, une consigne neutre suffit.

const d = $json;
if (d.decision !== "Modifier") return [];

const attempt = Number(d.attempt || 1) + 1;
const maxAttempts = 3;
if (attempt > maxAttempts) {
  throw new Error(`Nombre maximal de régénérations atteint pour ${d.jour}. Une intervention humaine est nécessaire.`);
}

const feedback = String(d.commentaire || "").trim() ||
  "La proposition précédente n'était pas exploitable. Reprends entièrement le contenu en respectant le schéma JSON, la ligne éditoriale et les faits TERA.";

return [{
  json: {
    jour: d.jour,
    famille: d.famille,
    variante: d.variante,
    target_due_at: d.target_due_at,
    attempt,
    modification_feedback: feedback,
    previous_render_items: d.renderItems || []
  }
}];
